* { box-sizing: border-box; }
[hidden] { display: none !important; }
:root { color-scheme: light; font-family: system-ui, sans-serif; font-size: 16px; color: #20253b; background: #f1edff; }
body { min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 24px 16px; background-color: #f1edff; background-image: linear-gradient(#dcd5ff 1px, transparent 1px), linear-gradient(90deg, #dcd5ff 1px, transparent 1px); background-size: 24px 24px; }
.card { width: min(100%, 520px); padding: clamp(24px, 7vw, 44px); background: #fff; border: 3px solid #292d49; box-shadow: 8px 8px 0 #292d49; }
.header { margin-bottom: 28px; }
.eyebrow { margin: 0 0 8px; color: #6654d9; font-weight: 800; letter-spacing: .12em; font-size: .9rem; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 8px; font-size: clamp(1.65rem, 6vw, 2rem); line-height: 1.2; }
.intro, .hint { color: #62677d; margin-bottom: 0; }
.progress-area { margin-bottom: 28px; }
.progress-label { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 9px; font-weight: 700; font-size: .95rem; }
.progress-track { height: 14px; border: 2px solid #292d49; background: #eeeaff; }
.progress-fill { width: 33.333%; height: 100%; background: #7664ed; transition: width .2s ease; }
.step h2 { font-size: 1.3rem; margin: 0 0 20px; }
.step > label { display: block; margin: 18px 0 7px; font-weight: 700; }
input[type="text"], input[type="email"] { width: 100%; min-height: 48px; padding: 11px 13px; border: 2px solid #a6a9ba; border-radius: 0; background: #fff; color: #20253b; font: inherit; }
input:focus-visible, button:focus-visible, .plan:focus-within { outline: 3px solid #7664ed; outline-offset: 3px; }
.plans { display: grid; gap: 12px; border: 0; padding: 0; margin: 20px 0 0; }
.plan { display: flex; align-items: center; gap: 12px; min-height: 74px; padding: 12px; border: 2px solid #c7c8d4; cursor: pointer; transition: border-color .15s, background .15s, transform .15s; }
.plan:hover { border-color: #7664ed; background: #f8f6ff; }
.plan:active { transform: translateY(1px); }
.plan:has(input:checked) { border-color: #6654d9; background: #f1edff; }
.plan input { width: 20px; height: 20px; accent-color: #6654d9; flex: 0 0 auto; }
.plan-copy { display: grid; gap: 3px; flex: 1; }
.plan-copy strong { font-size: 1.05rem; }
.plan-copy small { color: #62677d; font-size: .9rem; }
.price { font-weight: 800; white-space: nowrap; }
.price span { color: #62677d; font-size: .85rem; font-weight: 500; }
.summary { margin: 20px 0 4px; border-top: 2px solid #e5e3ed; }
.summary div { display: flex; justify-content: space-between; gap: 16px; padding: 14px 0; border-bottom: 2px solid #e5e3ed; }
.summary dt { color: #62677d; font-weight: 600; }
.summary dd { margin: 0; font-weight: 750; text-align: right; overflow-wrap: anywhere; }
.actions { display: flex; justify-content: flex-end; gap: 12px; margin-top: 28px; }
.button { min-height: 48px; padding: 10px 18px; border: 2px solid #292d49; border-radius: 0; font: inherit; font-weight: 750; cursor: pointer; transition: transform .12s, box-shadow .12s, background .12s; }
.button:hover:not(:disabled) { transform: translate(-2px, -2px); box-shadow: 3px 3px 0 #292d49; }
.button:active:not(:disabled) { transform: translateY(1px); box-shadow: none; }
.button:disabled { cursor: not-allowed; opacity: .48; }
.primary { color: #fff; background: #6654d9; }
.primary:hover:not(:disabled) { background: #5543c5; }
.secondary { color: #292d49; background: #fff; margin-right: auto; }
.error { color: #a12c40; margin: 16px 0 0; font-weight: 650; }
.success { margin: 18px 0 0; padding: 14px; color: #174b3c; background: #e4f6ee; border-left: 4px solid #3c9b76; font-weight: 700; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 400px) { .card { box-shadow: 5px 5px 0 #292d49; } .progress-label { font-size: .88rem; } .plan { gap: 9px; padding: 10px; } }

const form = document.querySelector('#signup-form');
const steps = [...document.querySelectorAll('.step')];
const nextButton = document.querySelector('#next-button');
const backButton = document.querySelector('#back-button');
const confirmButton = document.querySelector('#confirm-button');
const errorMessage = document.querySelector('#form-error');
const successMessage = document.querySelector('#success-message');
const progress = document.querySelector('[role="progressbar"]');
const progressFill = document.querySelector('.progress-fill');
const stepNames = ['Your details', 'Choose a plan', 'Review'];
let currentStep = 0;

function isStepValid() {
  if (currentStep === 0) {
    const name = document.querySelector('#name');
    const email = document.querySelector('#email');
    return name.value.trim().length >= 2 && email.validity.valid && email.value.trim() !== '';
  }
  if (currentStep === 1) return Boolean(form.querySelector('input[name="plan"]:checked'));
  return true;
}

function update() {
  steps.forEach((step, index) => { step.hidden = index !== currentStep; });
  document.querySelector('#step-label').textContent = `Step ${currentStep + 1} of 3`;
  document.querySelector('#step-name').textContent = stepNames[currentStep];
  progress.setAttribute('aria-valuenow', String(currentStep + 1));
  progressFill.style.width = `${((currentStep + 1) / 3) * 100}%`;
  backButton.hidden = currentStep === 0;
  nextButton.hidden = currentStep === 2;
  confirmButton.hidden = currentStep !== 2;
  nextButton.disabled = !isStepValid();
  errorMessage.hidden = true;
  if (currentStep === 2) {
    document.querySelector('#summary-name').textContent = document.querySelector('#name').value.trim();
    document.querySelector('#summary-email').textContent = document.querySelector('#email').value.trim();
    document.querySelector('#summary-plan').textContent = form.querySelector('input[name="plan"]:checked').value;
  }
}

function showValidationError() {
  errorMessage.textContent = currentStep === 0
    ? 'Enter a name with at least 2 characters and a valid email address.'
    : 'Choose a plan to continue.';
  errorMessage.hidden = false;
}

form.addEventListener('input', () => {
  nextButton.disabled = !isStepValid();
  errorMessage.hidden = true;
});
form.addEventListener('change', () => {
  nextButton.disabled = !isStepValid();
  errorMessage.hidden = true;
});
nextButton.addEventListener('click', () => {
  if (!isStepValid()) return showValidationError();
  currentStep += 1;
  update();
  steps[currentStep].querySelector('input, button')?.focus();
});
backButton.addEventListener('click', () => {
  currentStep -= 1;
  update();
  steps[currentStep].querySelector('input')?.focus();
});
form.addEventListener('submit', event => {
  event.preventDefault();
  if (currentStep !== 2) return;
  confirmButton.disabled = true;
  backButton.disabled = true;
  successMessage.hidden = false;
  successMessage.focus?.();
});

update();
